{
  "name": "@docuseal/signature-maker-vue",
  "version": "1.1.0",
  "description": "Vue component for drawing, typing and uploading signatures",
  "main": "dist/index.cjs.js",
  "module": "dist/index.esm.js",
  "types": "dist/index.d.ts",
  "files": [
    "dist",
    "!dist/*.tsbuildinfo"
  ],
  "author": "DocuSeal <support@docuseal.com>",
  "license": "MIT",
  "repository": "https://github.com/docusealco/signature-maker-vue",
  "homepage": "https://github.com/docusealco/signature-maker-vue#readme",
  "bugs": {
    "url": "https://github.com/docusealco/signature-maker-vue/issues"
  },
  "keywords": [
    "vue-signature",
    "signature",
    "signature-drawing",
    "signature-pad"
  ],
  "engines": {
    "node": ">=18"
  },
  "scripts": {
    "build": "node esbuild.config.js && tsc -p tsconfig.json",
    "typecheck": "tsc -p tsconfig.json --noEmit",
    "test": "playwright test",
    "prepublishOnly": "yarn build && yarn test"
  },
  "dependencies": {
    "@docuseal/signature-maker-js": "^1.1.1"
  },
  "peerDependencies": {
    "vue": "^3.3.0"
  },
  "devDependencies": {
    "@playwright/test": "^1.65.0",
    "@types/node": "^26.6.6",
    "esbuild": "^0.28.2",
    "typescript": "^5.9.3",
    "vue": "^3.5.45"
  }
}

import { createApp, defineComponent, h, ref } from 'vue'
import { SignatureMaker, type SignatureDetail } from '../src'

const events: { type: string; base64: string | null }[] = []

;(window as any).events = events

const App = defineComponent({
	setup() {
		const label = ref('Sign')
		const model = ref<string | null>(null)

		;(window as any).setLabel = (value: string) => (label.value = value)
		;(window as any).getModel = () => model.value

		return () =>
			h('div', [
				h(SignatureMaker, {
					class: 'my-signature',
					withUpload: false,
					saveButtonText: label.value,
					saveButtonClass: 'btn',
					saveButtonDisabledClass: 'btn-disabled',
					saveButtonsDisabledStyle: 'opacity: 0.5;',
					modelValue: model.value,
					'onUpdate:modelValue': (value: string | null) => (model.value = value),
					onSave: (detail: SignatureDetail) => events.push({ type: 'save', base64: detail.base64 }),
					onChange: (detail: SignatureDetail) => events.push({ type: 'change', base64: detail.base64 }),
					...((window as any).props || {}),
				}),
			])
	},
})

createApp(App).mount('#root')

import path from 'node:path'
import { build } from 'esbuild'
import { expect, test, type Page } from '@playwright/test'

const DIR = __dirname
const BUNDLE = path.join(DIR, '../test-results/app.js')

test.beforeAll(async () => {
	await build({
		entryPoints: [path.join(DIR, 'app.ts')],
		bundle: true,
		outfile: BUNDLE,
		define: {
			'process.env.NODE_ENV': '"development"',
			__VUE_OPTIONS_API__: 'true',
			__VUE_PROD_DEVTOOLS__: 'false',
			__VUE_PROD_HYDRATION_MISMATCH_DETAILS__: 'false',
		},
		logLevel: 'silent',
	})
})

async function mount(page: Page) {
	await page.setContent('<!doctype html><html><body style="width: 800px;"><div id="root"></div></body></html>')
	await page.addScriptTag({ path: BUNDLE })
	await page.waitForSelector('signature-maker canvas')
}

async function draw(page: Page) {
	const box = (await page.locator('signature-maker canvas').boundingBox())!

	await page.mouse.move(box.x + 50, box.y + 50)
	await page.mouse.down()
	await page.mouse.move(box.x + 200, box.y + 100, { steps: 10 })
	await page.mouse.up()
}

const events = (page: Page) => page.evaluate(() => (window as any).events as { type: string; base64: string | null }[])

test('maps props to attributes', async ({ page }) => {
	await mount(page)

	const el = page.locator('signature-maker')
	await expect(el).toHaveClass('my-signature')
	await expect(el).toHaveAttribute('data-with-upload', 'false')
	await expect(el).toHaveAttribute('data-save-button-text', 'Sign')
	await expect(el).not.toHaveAttribute('data-with-typed')
	await expect(el).not.toHaveAttribute('data-model-value')
	await expect(page.locator('[data-target="uploadTypeButton"]')).toBeHidden()
	await expect(page.locator('[data-target="saveButton"]')).toHaveText('Sign')
	await expect(page.locator('[data-target="saveButton"]')).toHaveAttribute('class', 'btn btn-disabled')
	await expect(el).toHaveAttribute('data-save-button-disabled-style', 'opacity: 0.5;')
})

test('re-renders when props change', async ({ page }) => {
	await mount(page)
	await page.evaluate(() => (window as any).setLabel('Done'))
	await expect(page.locator('[data-target="saveButton"]')).toHaveText('Done')
})

test('emits change, save and updates v-model', async ({ page }) => {
	await mount(page)
	await draw(page)

	await page.waitForFunction(() => (window as any).events.some((e: { base64: string | null }) => e.type === 'change' && e.base64))
	expect(await page.evaluate(() => (window as any).getModel())).toMatch(/^iVBORw0KGgo/)

	await page.locator('[data-target="saveButton"]').click()
	await page.waitForFunction(() => (window as any).events.some((e: { type: string }) => e.type === 'save'))
	expect((await events(page)).find((e) => e.type === 'save')!.base64).toMatch(/^iVBORw0KGgo/)

	await page.locator('[data-target="clearButton"]').click()
	await page.waitForFunction(() => (window as any).getModel() === null)
})

test('can be imported without a DOM', async () => {
	const cjs = require('../dist/index.cjs.js')

	expect(typeof cjs.SignatureMaker).toBe('object')
	expect(cjs.SignatureMaker.name).toBe('SignatureMaker')
})

const { build } = require("esbuild");

const shared = {
  bundle: true,
  entryPoints: ["./src/index.ts"],
  packages: "external",
  logLevel: "info",
  minify: true,
  sourcemap: false,
  target: "es2020",
};

Promise.all([
  build({ ...shared, format: "esm", outfile: "./dist/index.esm.js" }),
  build({ ...shared, format: "cjs", outfile: "./dist/index.cjs.js" }),
]);
